const response = pm.response.json();

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Booking response follows JSON schema", function () {
    pm.response.to.have.jsonSchema({
        type: "object",
        required: [
            "firstname",
            "lastname",
            "totalprice",
            "depositpaid",
            "bookingdates",
            "additionalneeds"
        ],
        properties: {
            firstname: { type: "string" },
            lastname: { type: "string" },
            totalprice: { type: "number" },
            depositpaid: { type: "boolean" },
            bookingdates: {
                type: "object",
                required: ["checkin", "checkout"],
                properties: {
                    checkin: { type: "string" },
                    checkout: { type: "string" }
                }
            },
            additionalneeds: { type: "string" }
        }
    });
});

pm.test("Firstname was updated", function () {
    pm.expect(response.firstname).to.eql("Michael Updated");
});

pm.test("Lastname is correct", function () {
    pm.expect(response.lastname).to.eql("Agudo");
});

pm.test("Total price was updated", function () {
    pm.expect(response.totalprice).to.eql(2000);
});

pm.test("Deposit status was updated", function () {
    pm.expect(response.depositpaid).to.eql(false);
});

pm.test("Additional needs were updated", function () {
    pm.expect(response.additionalneeds).to.eql("Airport pickup");
});

pm.test("Booking dates were updated", function () {
    pm.expect(response.bookingdates.checkin).to.eql("2026-12-01");
    pm.expect(response.bookingdates.checkout).to.eql("2026-12-10");
});

